import { useCallback, useEffect, useReducer, useRef } from 'react'
import { createSimulation, openSimulationStream, resetSimulation, stopSimulation } from '../services/simulations.js'

/*
 * State machine for one simulation run against the future backend.
 *   idle -> starting -> running -> finished | stopped | error
 * Everything shown comes from backend events. Nothing is generated by the frontend.
 */
export const INITIAL = { phase: 'idle', frame: null, telemetry: null, error: null }

export function reducer(state, action) {
  switch (action.type) {
    case 'starting':
      return { ...INITIAL, phase: 'starting' }
    case 'running':
      return { ...state, phase: 'running' }
    case 'frame':
      return { ...state, frame: action.frame }
    case 'state':
      return { ...state, telemetry: action.telemetry }
    case 'restarted':
      return { ...INITIAL, phase: 'running' }
    case 'finished':
      return { ...state, phase: 'finished' }
    case 'stopped':
      return { ...state, phase: 'stopped' }
    case 'error':
      return { ...state, phase: 'error', error: action.message }
    default:
      return state
  }
}

const messageOf = (error) => (error instanceof Error ? error.message : 'Something went wrong.')

export function useSimulation() {
  const [state, dispatch] = useReducer(reducer, INITIAL)
  const idRef = useRef(null)
  const closeRef = useRef(null)

  const closeStream = useCallback(() => {
    closeRef.current?.()
    closeRef.current = null
  }, [])

  const attach = useCallback(
    (id) => {
      closeStream()
      closeRef.current = openSimulationStream(id, {
        onFrame: (frame) => dispatch({ type: 'frame', frame: frame.image }),
        onState: (telemetry) => dispatch({ type: 'state', telemetry }),
        onEnd: () => dispatch({ type: 'finished' }),
        onError: (error) => dispatch({ type: 'error', message: messageOf(error) }),
      })
    },
    [closeStream],
  )

  const start = useCallback(
    async (params) => {
      closeStream()
      dispatch({ type: 'starting' })
      try {
        const { simulationId } = await createSimulation(params)
        idRef.current = simulationId
        attach(simulationId)
        dispatch({ type: 'running' })
      } catch (error) {
        dispatch({ type: 'error', message: messageOf(error) })
      }
    },
    [attach, closeStream],
  )

  const reset = useCallback(async () => {
    if (!idRef.current) return
    try {
      await resetSimulation(idRef.current)
      attach(idRef.current)
      dispatch({ type: 'restarted' })
    } catch (error) {
      dispatch({ type: 'error', message: messageOf(error) })
    }
  }, [attach])

  const stop = useCallback(async () => {
    closeStream()
    const id = idRef.current
    idRef.current = null
    dispatch({ type: 'stopped' })
    if (id) {
      try {
        await stopSimulation(id)
      } catch {
        // The run is already closed on this side; a failed cleanup call needs no extra message.
      }
    }
  }, [closeStream])

  // Leaving the page closes the stream and asks the backend to free the run.
  useEffect(
    () => () => {
      closeRef.current?.()
      if (idRef.current) stopSimulation(idRef.current).catch(() => {})
    },
    [],
  )

  return { state, start, reset, stop }
}
